// ponytail: frozen round0 coverage only. One point per identity, no grid,
// no optimizer, no parameter domain, no 43rd cell.
const SYMBOLS = ['BTCUSDT', 'ETHUSDT', 'BNBUSDT', 'SOLUSDT', 'XRPUSDT', 'DOGEUSDT', 'LINKUSDT'];
const TIMEFRAMES = ['1h', '4h', '1d'];
const LEVERAGES = [3, 5];
const expected = [];
for (const symbol of SYMBOLS)
  for (const timeframe of TIMEFRAMES)
    for (const research_leverage of LEVERAGES)
      expected.push(symbol + '-' + timeframe + '-x' + research_leverage);
if (expected.length !== 42 || new Set(expected).size !== 42)
  throw new Error('identity generator is not the frozen 42-cell set');
return expected.map((cell_id) => {
  const parts = cell_id.split('-');
  return { json: {
    cell_id,
    symbol: parts[0],
    timeframe: parts[1],
    research_leverage: Number(parts[2].slice(1)),
  } };
});

// Bind every frozen identity to exactly one materialized cell handoff.
// Fail closed: any duplicate, missing, extra or mismatched cell holds the whole
// campaign before a single run is submitted.
const input = $('01 · Campaign input').first().json;
const sd = $getWorkflowStaticData('global');
const parseManifest = (value) => {
  if (value == null || value === '') return null;
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const obj = JSON.parse(value);
      return (obj && typeof obj === 'object' && !Array.isArray(obj)) ? obj : null;
    } catch { return null; }
  }
  return null;
};
if (input.market_data_ready === false)
  throw new Error('CAMPAIGN HOLD: market data is not ready for this campaign');
const manifest = parseManifest(input.campaign_manifest);
if (!manifest || !Array.isArray(manifest.cells) || manifest.cells.length === 0)
  throw new Error('CAMPAIGN HOLD: frozen 42-cell manifest is missing');
const identities = $input.all().map((item) => item.json);
const isHex = (value, width) => typeof value === 'string' && new RegExp('^[a-f0-9]{' + width + '}$').test(value);
const isAbsPath = (value) => typeof value === 'string'
  && /^\/[A-Za-z0-9_@+./-]{1,511}$/.test(value) && !value.includes('..');
const VERIFIED = { execution: ['qlib-native-backtest'], data: ['btcusdt-1h'], timing: ['bar-close-1h'] };
const byId = new Map();
for (const cell of manifest.cells) {
  const id = cell && cell.cell_id;
  if (typeof id !== 'string' || id === '') throw new Error('CAMPAIGN HOLD: manifest cell has no identity');
  if (byId.has(id)) throw new Error('CAMPAIGN HOLD: duplicate cell in the manifest: ' + id);
  byId.set(id, cell);
}
if (byId.size !== identities.length)
  throw new Error('CAMPAIGN HOLD: manifest covers ' + byId.size + ' of ' + identities.length + ' cells');
const bound = [];
const runIdentities = new Map();
const handoffFields = ['source_commit', 'candidate_path', 'source_blob_sha', 'entrypoint_ref',
  'entrypoint_sha256', 'effective_config_ref', 'effective_config_sha256', 'qlib_runtime_commit'];
for (const identity of identities) {
  const cell = byId.get(identity.cell_id);
  if (!cell) throw new Error('CAMPAIGN HOLD: missing cell ' + identity.cell_id);
  if (cell.symbol !== identity.symbol || cell.timeframe !== identity.timeframe
      || cell.research_leverage !== identity.research_leverage)
    throw new Error('CAMPAIGN HOLD: identity mismatch for ' + identity.cell_id);
  for (const key of handoffFields)
    if (cell[key] == null) throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' is missing ' + key);
  if (!isHex(cell.source_commit, 40) || !isHex(cell.source_blob_sha, 40) || !isHex(cell.qlib_runtime_commit, 40))
    throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' has an invalid commit or blob shape');
  if (!isAbsPath(cell.entrypoint_ref) || !isHex(cell.entrypoint_sha256, 64))
    throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' has an invalid entrypoint binding');
  if (!isAbsPath(cell.effective_config_ref) || !isHex(cell.effective_config_sha256, 64))
    throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' has an invalid config binding');
  if (!cell.research_cost_model || typeof cell.research_cost_model !== 'object')
    throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' declares no research cost model');
  const declared = cell.capabilities && typeof cell.capabilities === 'object' ? cell.capabilities : VERIFIED;
  const gap = [];
  let declaredCount = 0;
  for (const bucket of Object.keys(declared)) {
    const values = Array.isArray(declared[bucket]) ? declared[bucket] : [declared[bucket]];
    for (const value of values) {
      declaredCount += 1;
      if (!(bucket in VERIFIED) || !VERIFIED[bucket].includes(value)) gap.push(bucket + ':' + value);
    }
  }
  if (declaredCount === 0) gap.push('capability declaration is missing');
  if (gap.length > 0)
    throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' declares unverified capability: ' + gap.join(', '));
  const runIdentity = [cell.source_blob_sha, cell.entrypoint_sha256, cell.effective_config_sha256,
    cell.qlib_runtime_commit].join(':');
  if (runIdentities.has(runIdentity))
    throw new Error('CAMPAIGN HOLD: ' + identity.cell_id + ' shares one run location with ' + runIdentities.get(runIdentity));
  runIdentities.set(runIdentity, identity.cell_id);
  const handoff = {
    source_commit: cell.source_commit,
    candidate_path: cell.candidate_path,
    source_blob_sha: cell.source_blob_sha,
    entrypoint_ref: cell.entrypoint_ref,
    entrypoint_sha256: cell.entrypoint_sha256,
    effective_config_ref: cell.effective_config_ref,
    effective_config_sha256: cell.effective_config_sha256,
    qlib_runtime_commit: cell.qlib_runtime_commit,
    capabilities: declared,
    evidence_refs: cell.evidence_refs && typeof cell.evidence_refs === 'object' ? cell.evidence_refs : {},
    research_cost_model: cell.research_cost_model,
    run_inputs: cell.run_inputs || {
      symbol: identity.symbol, timeframe: identity.timeframe, research_leverage: identity.research_leverage,
    },
  };
  bound.push({
    json: {
      ...identity,
      executable_handoff: handoff,
      research_cost_declared: handoff.research_cost_model != null || handoff.run_inputs != null,
      cost_model_approved: handoff.research_cost_model && handoff.research_cost_model.approved === true,
      run_state: 'NOT_SUBMITTED',
      transport_payload_b64: Buffer.from(JSON.stringify(handoff), 'utf8').toString('base64'),
    },
  });
}
// ponytail: internal grouping key for the campaign ledger, not evidence. A cheap
// deterministic string hash is enough; the frozen cell separation already rides
// on the materialized sha256 hashes above.
const hash = (text) => {
  let a = 0x811c9dc5;
  let b = 0x1000193;
  for (const code of text) {
    a = (a ^ code) * 0x01000193 >>> 0;
    b = (b + code * 31) >>> 0;
  }
  return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
};
const campaign_run_key = hash(bound.map((item) => item.json.cell_id + ':' + item.json.executable_handoff.effective_config_sha256).join('|'));
sd.campaign_run_key = campaign_run_key;
sd.campaign_expected = bound.map((item) => item.json.cell_id);
sd.campaign_records = [];
return bound;

const ssh = $input.first().json;
const cell = $('03 · Loop over 42 cells').item.json;
const handoff = cell.executable_handoff;
if (!handoff || typeof handoff !== 'object' || Array.isArray(handoff))
  throw new Error('CAMPAIGN HOLD: validated cell handoff is missing');
if (ssh.code !== 0) throw new Error('CAMPAIGN HOLD: Node04 SSH command failed for ' + cell.cell_id);
let receipt;
try { receipt = JSON.parse(String(ssh.stdout || '').trim()); }
catch { throw new Error('CAMPAIGN HOLD: Node04 receipt is not JSON for ' + cell.cell_id); }
if (!receipt || typeof receipt !== 'object' || Array.isArray(receipt) || receipt.node04 !== 'PASS')
  throw new Error('CAMPAIGN HOLD: Node04 receipt is not PASS for ' + cell.cell_id);
if (receipt.candidate_blob_sha !== handoff.source_blob_sha)
  throw new Error('CAMPAIGN HOLD: Node04 candidate identity mismatch for ' + cell.cell_id);
if (receipt.candidate_path !== handoff.candidate_path)
  throw new Error('CAMPAIGN HOLD: Node04 candidate path mismatch for ' + cell.cell_id);
if (receipt.entrypoint_sha256 !== handoff.entrypoint_sha256)
  throw new Error('CAMPAIGN HOLD: Node04 entrypoint binding mismatch for ' + cell.cell_id);
if (receipt.effective_config_sha256 !== handoff.effective_config_sha256)
  throw new Error('CAMPAIGN HOLD: Node04 effective_config binding mismatch for ' + cell.cell_id);
if (!/^[a-f0-9]{32}$/.test(String(receipt.run_id || '')))
  throw new Error('CAMPAIGN HOLD: Node04 run_id is missing or invalid for ' + cell.cell_id);
if (!/^[0-9]+$/.test(String(receipt.experiment_id || '')))
  throw new Error('CAMPAIGN HOLD: Node04 experiment_id is missing or invalid for ' + cell.cell_id);
// The frozen transport prints no cost flag: the fact lives only in the on-disk
// submit receipt. The cost fact is the handoff's, under the transport's own
// rule (research_cost_model or run_inputs), never the stdout receipt.
const costDeclared = handoff.research_cost_model != null || handoff.run_inputs != null;
if (!costDeclared)
  throw new Error('CAMPAIGN HOLD: Node04 research cost is not declared for ' + cell.cell_id);
return [{ json: { ...cell, qlib_run_id: receipt.run_id, run_state: 'FINISHED', node04_receipt: receipt } }];

const ssh = $input.first().json;
const submitted = $('05 · Verify cell submit receipt').item.json;
const handoff = submitted.executable_handoff;
if (!handoff || typeof handoff !== 'object' || Array.isArray(handoff))
  throw new Error('CAMPAIGN HOLD: validated cell handoff is missing');
if (ssh.code !== 0) throw new Error('CAMPAIGN HOLD: Node05 SSH command failed for ' + submitted.cell_id);
let receipt;
try { receipt = JSON.parse(String(ssh.stdout || '').trim()); }
catch { throw new Error('CAMPAIGN HOLD: Node05 receipt is not JSON for ' + submitted.cell_id); }
if (!receipt || typeof receipt !== 'object' || Array.isArray(receipt) || receipt.node05 !== 'PASS')
  throw new Error('CAMPAIGN HOLD: Node05 receipt is not PASS for ' + submitted.cell_id);
if (receipt.run_id !== submitted.qlib_run_id)
  throw new Error('CAMPAIGN HOLD: Node05 run identity mismatch for ' + submitted.cell_id);
if (receipt.candidate_path !== handoff.candidate_path || receipt.candidate_blob_sha !== handoff.source_blob_sha)
  throw new Error('CAMPAIGN HOLD: Node05 candidate identity mismatch for ' + submitted.cell_id);
if (receipt.status !== 'FINISHED' || submitted.run_state !== 'FINISHED')
  throw new Error('CAMPAIGN HOLD: run is not FINISHED for ' + submitted.cell_id);
for (const key of ['params_count', 'metrics_count', 'artifacts_count'])
  if (!Number.isSafeInteger(receipt[key]) || receipt[key] <= 0)
    throw new Error('CAMPAIGN HOLD: missing or empty ' + key + ' for ' + submitted.cell_id);
const submittedReceipt = submitted.node04_receipt || {};
if (typeof receipt.out_dir !== 'string' || receipt.out_dir !== submittedReceipt.out_dir)
  throw new Error('CAMPAIGN HOLD: run location does not match the submit receipt for ' + submitted.cell_id);
if (receipt.experiment_id !== submittedReceipt.experiment_id)
  throw new Error('CAMPAIGN HOLD: experiment identity mismatch for ' + submitted.cell_id);
const runRef = receipt.out_dir + '/mlruns/' + receipt.experiment_id + '/' + receipt.run_id;
if (!receipt.refs || receipt.refs.mlflow_run !== runRef)
  throw new Error('CAMPAIGN HOLD: run reference mismatch for ' + submitted.cell_id);
if (receipt.refs.candidate !== 'https://api.github.com/repos/HCH725/alpha-strategy-research/git/blobs/'
  + handoff.source_blob_sha)
  throw new Error('CAMPAIGN HOLD: candidate reference mismatch for ' + submitted.cell_id);
for (const [key, ref] of Object.entries(handoff.evidence_refs || {})) {
  if (key === 'candidate') continue;
  if (!receipt.refs || receipt.refs[key] !== ref)
    throw new Error('CAMPAIGN HOLD: evidence reference mismatch ' + key + ' for ' + submitted.cell_id);
}
for (const key of ['candidate', 'data', 'execution', 'runtime', 'evidence'])
  if (!receipt.readable || receipt.readable[key] !== true)
    throw new Error('CAMPAIGN HOLD: unreadable ' + key + ' evidence for ' + submitted.cell_id);
if (receipt.manifest_verified !== true || receipt.manifest_readback_run_id !== submitted.qlib_run_id
  || !/^[a-f0-9]{64}$/.test(String(receipt.manifest_sha256 || '')))
  throw new Error('CAMPAIGN HOLD: manifest or run identity mismatch for ' + submitted.cell_id);
// A single cell keeps the transport semantics: coverage_complete stays false and
// claimability is derived, never asserted here.
const derived = receipt.coverage_complete === true && receipt.manifest_verified === true
  && (handoff.research_cost_model != null || handoff.run_inputs != null);
if (receipt.performance_claimable !== derived)
  throw new Error('CAMPAIGN HOLD: performance_claimable is not derived for ' + submitted.cell_id);
const sd = $getWorkflowStaticData('global');
if (!sd.campaign_run_key) throw new Error('CAMPAIGN HOLD: no campaign run is open');
if (!Array.isArray(sd.campaign_records)) sd.campaign_records = [];
sd.campaign_records.push({
  campaign_run_key: sd.campaign_run_key,
  cell_id: submitted.cell_id,
  symbol: submitted.symbol,
  timeframe: submitted.timeframe,
  research_leverage: submitted.research_leverage,
  effective_config_sha256: handoff.effective_config_sha256,
  entrypoint_sha256: handoff.entrypoint_sha256,
  qlib_run_id: submitted.qlib_run_id,
  experiment_id: receipt.experiment_id,
  out_dir: receipt.out_dir,
  receipt_sha256: receipt.manifest_sha256,
  node05_pass: true,
  evidence_complete: receipt.manifest_verified === true,
  cost_declared: handoff.research_cost_model != null || handoff.run_inputs != null,
  cost_model_approved: handoff.research_cost_model && handoff.research_cost_model.approved === true,
});
return [{ json: { cell_id: submitted.cell_id, qlib_run_id: submitted.qlib_run_id,
  performance_claimable: derived, run_state: 'FINISHED' } }];

// Deterministic campaign coverage aggregate. Only a complete, clean 42/42
// receipt set declares coverage; only an approved declared research cost model
// makes the campaign claimable. Anything else is a HOLD with named gaps.
const sd = $getWorkflowStaticData('global');
const runKey = sd.campaign_run_key;
if (!runKey) throw new Error('CAMPAIGN HOLD: no campaign run is open');
const expectedIds = Array.isArray(sd.campaign_expected) ? sd.campaign_expected.slice() : [];
const allRecords = Array.isArray(sd.campaign_records) ? sd.campaign_records : [];
const records = allRecords.filter((record) => record && record.campaign_run_key === runKey);
const gaps = [];
if (expectedIds.length !== 42 || new Set(expectedIds).size !== 42)
  gaps.push('frozen identity set is not 42 unique cells');
const expectedSet = new Set(expectedIds);
const seen = new Map();
for (const record of records) {
  if (!expectedSet.has(record.cell_id)) { gaps.push('unknown cell: ' + record.cell_id); continue; }
  if (seen.has(record.cell_id)) { gaps.push('duplicate cell: ' + record.cell_id); continue; }
  seen.set(record.cell_id, record);
  if (record.node05_pass !== true) gaps.push('Node05 not PASS: ' + record.cell_id);
  if (record.evidence_complete !== true) gaps.push('evidence incomplete: ' + record.cell_id);
  if (!/^[a-f0-9]{32}$/.test(String(record.qlib_run_id || ''))) gaps.push('missing Qlib run: ' + record.cell_id);
  if (!/^[a-f0-9]{64}$/.test(String(record.effective_config_sha256 || ''))) gaps.push('missing config binding: ' + record.cell_id);
  if (!/^[0-9]+$/.test(String(record.experiment_id || ''))) gaps.push('missing experiment reference: ' + record.cell_id);
  if (record.symbol == null || record.timeframe == null || record.research_leverage == null)
    gaps.push('missing identity fields: ' + record.cell_id);
}
for (const cellId of expectedIds)
  if (!seen.has(cellId)) gaps.push('missing cell: ' + cellId);
const costDeclared = records.length > 0 && records.every((record) => record.cost_declared === true);
const costApproved = records.length > 0 && records.every((record) => record.cost_model_approved === true);
if (!costDeclared) gaps.push('research cost is not declared for every cell');
const coverageComplete = gaps.length === 0 && seen.size === 42;
const performanceClaimable = coverageComplete && costDeclared && costApproved;
if (coverageComplete && !costApproved)
  gaps.push('research cost model is declared but not approved; performance stays unclaimable');
const campaign = {
  campaign_run_key: runKey,
  expected_cells: expectedIds.length,
  observed_cells: records.length,
  node05_pass_cells: records.filter((record) => record.node05_pass === true).length,
  coverage_complete: coverageComplete,
  evidence_complete: coverageComplete,
  research_cost_declared: costDeclared,
  cost_model_approved: costApproved,
  performance_claimable: performanceClaimable,
  route: coverageComplete && costApproved ? 'PASS' : 'HOLD',
  gaps: gaps.slice(0, 42),
};
sd.campaign_last_aggregate = campaign;
return [{ json: campaign }];

const campaign = $input.first().json;
if (campaign.coverage_complete !== true)
  throw new Error('CAMPAIGN HOLD: coverage is not complete (' + campaign.observed_cells + '/' + campaign.expected_cells + '): '
    + campaign.gaps.join('; '));
if (campaign.performance_claimable !== true)
  throw new Error('CAMPAIGN HOLD: coverage is complete but the campaign is not claimable: ' + campaign.gaps.join('; '));
return [{ json: campaign }];
